---
import type { HTMLAttributes } from "astro/types"

import { cn } from "@/lib/utils"
import type { ToggleVariantProps } from "@/components/ui/toggle"

type Props = HTMLAttributes<"div"> &
  ToggleVariantProps & {
    defaultValue?: string | string[]
    multiple?: boolean
    orientation?: "horizontal" | "vertical"
    loop?: boolean
    disabled?: boolean
    spacing?: number
  }

const {
  class: className,
  style,
  defaultValue,
  multiple,
  orientation = "horizontal",
  loop,
  disabled,
  variant,
  size,
  spacing = 2,
  ...props
} = Astro.props

const serializedDefaultValue = Array.isArray(defaultValue)
  ? defaultValue.join(" ")
  : defaultValue

const resolvedStyle =
  typeof style === "string"
    ? `--gap: ${spacing}; ${style}`
    : { "--gap": spacing, ...(style ?? {}) }
---

<div
  role="group"
  data-slot="toggle-group"
  data-default-value={serializedDefaultValue}
  data-multiple={multiple ? "" : undefined}
  data-orientation={orientation}
  data-horizontal={orientation === "horizontal" ? "" : undefined}
  data-vertical={orientation === "vertical" ? "" : undefined}
  data-loop={loop}
  data-disabled={disabled ? "" : undefined}
  data-variant={variant}
  data-size={size}
  data-spacing={spacing}
  style={resolvedStyle}
  class={cn(
    "data-[spacing=0]:data-[variant=outline]:rounded-2xl group/toggle-group flex w-fit flex-row items-center gap-[--spacing(var(--gap))] data-vertical:flex-col data-vertical:items-stretch [&[data-orientation=horizontal][data-spacing='0'][data-variant=outline]>[data-slot=toggle-group-item]:not(:first-child)]:border-l-0 [&[data-orientation=vertical][data-spacing='0'][data-variant=outline]>[data-slot=toggle-group-item]:not(:first-child)]:border-t-0 [&[data-spacing='0']>[data-slot=toggle-group-item]]:shadow-none",
    className
  )}
  {...props}
>
  <slot />
</div>

<script>
  import { create } from "@data-slot/toggle-group"

  const controllers: ReturnType<typeof create> = []
  const initialize = () => controllers.push(...create())
  initialize()
  document.addEventListener("astro:page-load", initialize)
  document.addEventListener("astro:before-swap", () => {
    for (const controller of controllers) controller.destroy()
    controllers.length = 0
  })
</script>
